/**
 * Finds a domestic Pakistani city or delivery area by exact or loose name match
 */
export function findDomesticCity(query: string, customList?: DomesticCity[]): DomesticCity | undefined {
  if (!query) return undefined;
  const q = query.trim().toLowerCase();
  const list = customList && customList.length > 0 ? customList : pakistanCitiesList;

  // Exact match
  const exact = list.find((c) => c.name.toLowerCase() === q);
  if (exact) return exact;

  // By delivery code (e.g. KHI, LHE, ISB)
  const byCode = list.find((c) => c.deliveryCode && c.deliveryCode.toLowerCase() === q);
  if (byCode) return byCode;

  // Substring match
  const sub = list.find(
    (c) =>
      c.name.toLowerCase().includes(q) ||
      q.includes(c.name.toLowerCase()) ||
      (c.areaGroup && c.areaGroup.toLowerCase().includes(q))
  );
  if (sub) return sub;

  return undefined;
}
